define(["jquery"],function($){"use strict";function getString(key,fallback){var component="proctoringpolicy_password";try{if(window.M&&window.M.util&&window.M.util.get_string){return window.M.util.get_string(key,component)}}catch(e){}return fallback||""}function init(config){if(!config||!config.url){return}var $container=$('[data-region="password-admin-content"]');var $meta=$('[data-region="password-admin-meta"]');if($container.length===0){return}var loading=false;var refresh=function(){if(loading){return}loading=true;$.ajax({url:config.url,method:"GET",dataType:"json"}).done(function(response){if(!response){return}if(typeof response.html==="string"){$container.html(response.html)}if($meta.length&&response.lastupdated){$meta.text(getString("admin_refreshing","Automatically refreshing every 10 seconds.")+" "+response.lastupdated)}}).always(function(){loading=false})};window.setInterval(refresh,Number(config.interval||1e4))}return{init:init}});